export const SERVICE='https://gis.ngdc.noaa.gov/arcgis/rest/services/EMAG2v3/ImageServer';
export function distance(a,b,c,d){const r=Math.PI/180,p=(c-a)*r,q=(d-b)*r;return 6371.0088*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(p/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin(q/2)**2)));}
export function grid(lat,lon,radius){const points=[];const dy=(radius+9)/110;const dx=Math.min(180,(radius+9)/(110*Math.cos(lat*Math.PI/180)));for(let y=Math.max(0,Math.floor((lat-dy+90)*30));y<Math.min(5400,Math.ceil((lat+dy+90)*30));y++){for(let x=Math.floor((lon-dx+180)*30);x<Math.ceil((lon+dx+180)*30);x++){const la=-90+(y+.5)/30,lo=((x+.5)/30%360+360)%360-180;const km=distance(lat,lon,la,lo);if(km<=radius+7)points.push({lat:la,lon:lo,km,x:(x%10800+10800)%10800,y});}}return points;}
export async function analyze(lat,lon,radius,onProgress=()=>{}){const points=grid(lat,lon,radius);let next=0,done=0;async function worker(){while(next<points.length){const start=next;next+=100;const batch=points.slice(start,start+100);const params=new URLSearchParams({f:'json',geometryType:'esriGeometryMultipoint',geometry:JSON.stringify({points:batch.map(p=>[p.lon,p.lat]),spatialReference:{wkid:4326}}),returnFirstValueOnly:'true',interpolation:'RSP_NearestNeighbor',pixelSize:JSON.stringify({x:1/30,y:1/30,spatialReference:{wkid:4326}})});let json;for(let attempt=0;attempt<3;attempt++){try{const response=await fetch(SERVICE+'/getSamples?'+params,{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('HTTP '+response.status);json=await response.json();if(json.error)throw Error(json.error.message);break;}catch(e){if(attempt===2)throw e;}}for(const s of json.samples??[]){const p=batch[s.locationId];const v=Number(s.value);if(p&&s.value!==''&&s.value!=='NoData'&&Number.isFinite(v)&&Math.abs(v)<1e6)p.value=v;}done+=batch.length;onProgress(done/points.length);}}await Promise.all([worker(),worker(),worker()]);return summarize(points,lat,lon,radius);}
export function summarize(points,lat,lon,radius,width=10800){const lookup=new Map(points.filter(p=>Number.isFinite(p.value)).map(p=>[p.x+','+p.y,p]));for(const p of points){const l=lookup.get(((p.x+width-1)%width)+','+p.y),r=lookup.get(((p.x+1)%width)+','+p.y),b=lookup.get(p.x+','+(p.y-1)),t=lookup.get(p.x+','+(p.y+1));if(l&&r&&b&&t)p.gradient=Math.hypot((r.value-l.value)/distance(l.lat,l.lon,r.lat,r.lon),(t.value-b.value)/distance(b.lat,b.lon,t.lat,t.lon));}const inside=points.filter(p=>p.km<=radius);const valid=inside.filter(p=>Number.isFinite(p.value));if(!valid.length)throw Error('A fonte não retornou dados válidos para esta área.');return {lat,lon,radius,date:new Date().toISOString(),total:inside.length,points:valid};}
export function ranking(data,type){return data.points.filter(p=>type==='positive'?p.value>0:type==='negative'?p.value<0:Number.isFinite(p.gradient)).sort((a,b)=>type==='positive'?b.value-a.value:type==='negative'?a.value-b.value:b.gradient-a.gradient).slice(0,10);}
